// The fine coastline tiles (ADR-207): where they come from and how one is loaded.
//
// `geoTileData/*.json` is generated by `scripts/gen-world-outline.mjs --tiles` from the same Natural
// Earth 1:10m data as `worldOutline.ts`, simplified at ≈110 m instead of ≈3.3 km and cut into
// `GEO_TILE_DEG`° squares. Each file is its own chunk, fetched from the WebUI's own server only
// when the pane is zoomed in over it — nothing leaves the deployment, so the map still works on a
// management network with no egress.

import { useEffect, useMemo, useRef, useState } from 'react';
import { GEO_TILE_UNITS } from './geoProjection';

/**
 * One tile, in integer thousandths of a map unit relative to its top-left corner.
 *
 * `land` and `water` are filled shapes, clipped slightly beyond the square so neighbours overlap
 * rather than leave a seam, and must be drawn **without** a stroke — their clipped edges are not
 * coastline. `coast` is the shoreline (land and water both) clipped exactly to the square, as open
 * lines: the only list that is stroked.
 */
export interface GeoTile {
  land: string[];
  water: string[];
  coast: string[];
}

/** The scale from a tile's path units to map units. */
export const GEO_TILE_PATH_SCALE = 1 / 1000;

const TILE_MODULES = import.meta.glob<GeoTile>('./geoTileData/*.json', { import: 'default' });

/** `"<col>_<row>"` → its loader. Ocean tiles have no entry. */
const LOADERS = new Map(
  Object.entries(TILE_MODULES).map(([path, load]) => [tileKeyOf(path), load] as const),
);

/** `./geoTileData/t31_5.json` → `31_5`. */
export function tileKeyOf(path: string): string {
  const m = /t(\d+_\d+)\.json$/.exec(path);
  if (!m) throw new Error(`not a geo tile: ${path}`);
  return m[1];
}

/** Whether a tile has a file (it holds some land or inland water). */
export function hasGeoTile(key: string): boolean {
  return LOADERS.has(key);
}

/** Load one tile; rejects for a key with no file. */
export function loadGeoTile(key: string): Promise<GeoTile> {
  const load = LOADERS.get(key);
  return load ? load() : Promise.reject(new Error(`no geo tile ${key}`));
}

/** A tile's top-left corner in map units. */
export function tileOrigin(key: string): { x: number; y: number } {
  const [c, r] = key.split('_').map(Number);
  return { x: c * GEO_TILE_UNITS, y: r * GEO_TILE_UNITS };
}

/** Keep the keys that have a file, in a stable order, so an unchanged set compares equal. */
export function wantedTiles(visible: readonly string[]): string[] {
  return visible.filter(hasGeoTile).sort();
}

/**
 * The fine tiles to draw for these visible keys: every one already loaded, in `keys` order.
 *
 * A tile still loading (or that failed to) is simply absent, and the page goes on drawing the world
 * outline there — a slow or broken chunk costs detail, never the map. Loaded tiles are kept for
 * the life of the page, so panning back over one does not fetch it again.
 */
export function useGeoTiles(keys: readonly string[]): [string, GeoTile][] {
  const loaded = useRef(new Map<string, GeoTile>());
  const asked = useRef(new Set<string>());
  // Bumped when a tile arrives, so the memo below re-reads `loaded`.
  const [arrivals, setArrivals] = useState(0);
  const joined = keys.join(',');
  // Per page, not per effect run: a tile asked for before the keys moved on must still be shown
  // when it arrives, whatever the keys are by then.
  const mounted = useRef(true);
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  useEffect(() => {
    for (const key of joined ? joined.split(',') : []) {
      // Asked once per page: a tile that failed is not retried on every pan, it stays coarse.
      if (asked.current.has(key)) continue;
      asked.current.add(key);
      loadGeoTile(key)
        .then((tile) => {
          loaded.current.set(key, tile);
          if (mounted.current) setArrivals((n) => n + 1);
        })
        .catch(() => {
          // Detail only: the world outline stays drawn under this tile.
        });
    }
  }, [joined]);

  return useMemo(
    () =>
      (joined ? joined.split(',') : []).flatMap((k): [string, GeoTile][] => {
        const t = loaded.current.get(k);
        return t ? [[k, t]] : [];
      }),
    // `arrivals` is the signal that `loaded` changed.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [joined, arrivals],
  );
}
